 weaponPivot=new THREE.Group();weaponPivot.position.set(.49,1.13,.08);arms[1].add(weaponPivot);const blade=new THREE.Mesh(new THREE.BoxGeometry(.11,.82,.055),steel);blade.position.y=-.2;blade.rotation.z=-.1;weaponPivot.add(blade);const cross=new THREE.Mesh(new THREE.BoxGeometry(.35,.07,.11),gold);cross.position.y=-.61;weaponPivot.add(cross);const grip=new THREE.Mesh(new THREE.CylinderGeometry(.035,.045,.24,7),boot);grip.position.y=-.71;weaponPivot.add(grip);
 g.userData={arms,legs,attack:0,blade,torso};return g;
