function skillEffect(skill){const color={strike:0xf2bc68,sweep:0xa982eb,heal:0x84dca1,ultimate:0xff744e}[skill];if(skill==='heal'){const beam=new THREE.Mesh(new THREE.CylinderGeometry(.24,.5,2.1,12,1,true),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.5,side:THREE.DoubleSide}));beam.position.copy(player.position).add(new THREE.Vector3(0,1.2,0));worldScene.add(beam);effects.push({mesh:beam,life:.7,max:.7,kind:'grow'})}else{const ring=new THREE.Mesh(new THREE.TorusGeometry(skill==='ultimate'?2.4:1.55,.09,7,32),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));ring.rotation.x=Math.PI/2;ring.position.set(player.position.x,.16,player.position.z-.2);worldScene.add(ring);effects.push({mesh:ring,life:.65,max:.65,kind:'ring'});createBurst(player.position,color)}}
