from pathlib import Path
for f in ['styles.css','game.js','index.html']:
 print('\n###', f)
 s=Path(f).read_text()
 if f=='styles.css':
  print(s.replace('}', '}\n'))
 elif f=='index.html':
  print(s)
 else:
  for i,line in enumerate(s.splitlines(),1):
   if any(x in line for x in ['function renderShop','SHOP_PRODUCTS','function applyShopSkin','boss-intro','function createPlayer','function bindEvents','function init']): print(f'{i}: {line}')
