content.text:
### styles.css
*{box-sizing:border-box}
 :root{--gold:#d5ad68;--gold-bright:#f4d28d;--ink:#090b0e;--panel:#11151a;--line:rgba(222,193,137,.2);--muted:#93949a;--red:#bd5756;--green:#73bd8d}
 html,body,#game-shell{margin:0;width:100%;height:100%;overflow:hidden;background:#090b0e;color:#f1eee8;font-family:Inter,Arial,sans-serif;touch-action:manipulation}
button{font:inherit;color:inherit;border:0;cursor:pointer;-webkit-tap-highlight-color:transparent}
#game-shell{position:relative;isolation:isolate}
#world{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 42%,#35302a 0,#171719 40%,#090b0e 100%);z-index:-3}
#world canvas{display:block;width:100%;height:100%}
.vignette{position:absolute;inset:0;pointer-events:none;z-index:-2;background:linear-gradient(180deg,rgba(5,7,9,.58),transparent 25%,transparent 62%,rgba(5,7,9,.74)),radial-gradient(ellipse at center,transparent 42%,rgba(4,5,7,.35) 100%)}
.topbar{position:absolute;inset:env(safe-area-inset-top,0) 0 auto;min-height:64px;display:flex;align-items:center;padding:11px clamp(14px,4vw,36px);gap:10px;z-index:5;background:linear-gradient(180deg,rgba(7,9,11,.83),rgba(7,9,11,.15));}
.brand{display:flex;align-items:center;gap:10px;margin-right:auto}
.brand-mark{width:37px;height:37px;border:1px solid #a68a58;color:var(--gold-bright);display:grid;place-items:center;transform:rotate(45deg);font-size:20px;text-shadow:0 0 12px #ddb96b}
.brand-title{font:700 18px Cinzel,serif;letter-spacing:1.6px}
.brand-title em{color:var(--gold-bright);font-style:normal}
.brand-subtitle{font:600 8px Inter,sans-serif;letter-spacing:3.5px;color:#b1a58f;margin-top:1px}
.icon-button,.profile-button{height:36px;border:1px solid rgba(220,190,135,.25);background:rgba(15,17,20,.78);color:#d7c6a4}
.icon-button{width:38px;border-radius:4px;font-size:19px}
.profile-button{display:flex;align-items:center;gap:8px;padding:0 10px;border-radius:3px;font-size:10px;font-weight:700;letter-spacing:.6px}
.profile-button b{display:grid;place-items:center;width:22px;height:22px;background:#655330;color:#ffe0a2;border:1px solid #d5ad68;border-radius:50%;font:700 12px Cinzel}
.profile-icon{font-size:17px;color:var(--gold)}
.combat-hud{position:absolute;top:76px;left:clamp(14px,4vw,38px);right:clamp(14px,4vw,38px);z-index:3;display:grid;grid-template-columns:1fr minmax(210px,310px);grid-template-rows:auto auto;gap:15px;align-items:start;pointer-events:none}
.location{display:flex;align-items:center;gap:9px;color:#f3e7d0;text-shadow:0 2px 6px #000}
.location-icon{font-size:22px;color:var(--gold)}
.location strong{font:600 11px Cinzel,serif;letter-spacing:1px}
.location small{display:block;color:#a8a39a;font-size:8px;letter-spacing:1.5px;margin-top:3px}
.target-card{background:linear-gradient(110deg,rgba(12,13,16,.91),rgba(19,18,18,.74));border:1px solid rgba(189,87,86,.45);padding:10px 12px 8px;box-shadow:0 8px 22px #0008;min-height:69px}
.target-heading,.target-meta,.player-name-row,.xp-row{display:flex;justify-content:space-between;align-items:center}
.target-heading{font:700 9px Inter,sans-serif;letter-spacing:1px}
.target-heading span:last-child{font-size:8px;color:#c5b99f}
.bar{height:6px;background:#29282a;overflow:hidden;border-radius:1px}
.enemy-bar{margin:8px 0 5px;height:7px}
.enemy-bar i,.hp-bar i,.xp-bar i{display:block;width:100%;height:100%;transition:width .25s ease}
.enemy-bar i{background:linear-gradient(90deg,#862f35,#d75e54);box-shadow:0 0 9px #b84242}
.target-meta{color:#8e8d8a;font-size:8px}
.target-meta span:last-child{letter-spacing:1px}
.player-bars{grid-column:1;grid-row:2;max-width:380px}
.player-line{display:flex;gap:9px;align-items:center}
.portrait{width:32px;height:32px;display:grid;place-items:center;background:linear-gradient(135deg,#4c3b25,#181716);border:1px solid #a58753;color:#f0d7a2;font-size:20px;box-shadow:0 0 13px #d5ad6830}
.player-data{flex:1}
.player-name-row{font-size:8px;letter-spacing:.7px;margin-bottom:5px;text-shadow:0 1px 5px #000}
.player-name-row span{color:#e2d9cb;font-size:9px}
.hp-bar{height:8px;border:1px solid #090b0d;background:#331c1e}
.hp-bar i{background:linear-gradient(90deg,#812e31,#d9625a)}
.xp-row{margin-top:5px;gap:7px;color:#e3c782;font-size:7px;font-weight:700;letter-spacing:.5px}
.xp-bar{height:4px;flex:1;background:#272a2e}
.xp-bar i{background:linear-gradient(90deg,#998040,#e2cb79)}
.xp-row span:last-child{color:#ddd3bf;font-weight:500;letter-spacing:0}
.currency{position:absolute;right:0;top:88px;display:flex;align-items:center;gap:7px;padding:6px 9px;background:#101114b9;border:1px solid #d1ab6338;color:#f1dfb8;font-size:11px;font-weight:700;pointer-events:auto}
.coin{color:#e4ba65}
.currency button{background:transparent;color:var(--gold);font-size:16px;padding:0 2px}
.combat-feedback{position:absolute;z-index:2;top:38%;left:50%;transform:translate(-50%,-50%);font:700 20px Cinzel,serif;color:#ffe7ab;text-shadow:0 0 13px #df9d41,0 2px 4px #000;pointer-events:none;opacity:0;white-space:nowrap}
.combat-feedback.show{animation:feedback .9s ease forwards}
@keyframes feedback{0%{opacity:0;transform:translate(-50%,0) scale(.8)}
20%{opacity:1}
100%{opacity:0;transform:translate(-50%,-36px) scale(1.05)}
}
.boss-warning{position:absolute;top:32%;left:50%;transform:translate(-50%,-50%);font:700 12px Cinzel,serif;letter-spacing:2px;color:#ff8170;text-shadow:0 0 18px #d22;display:none;white-space:nowrap}
.boss-warning.show{display:block;animation:warn 2.8s ease forwards}
@keyframes warn{0%,100%{opacity:0}
15%,75%{opacity:1}
}
.skill-dock{position:absolute;z-index:4;right:clamp(15px,4vw,38px);bottom:105px;display:flex;gap:9px;align-items:end}
.skill-button{position:relative;width:65px;height:78px;background:linear-gradient(145deg,rgba(32,32,33,.93),rgba(10,12,15,.95));border:1px solid rgba(204,171,105,.57);clip-path:polygon(10% 0,90% 0,100% 12%,100% 100%,0 100%,0 12%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;box-shadow:0 5px 15px #0008;transition:transform .12s,border-color .2s}
.skill-button:active{transform:scale(.92)}
.skill-icon{font-size:22px;line-height:24px;color:#e0bf79;text-shadow:0 0 12px currentColor}
.sweep-icon{color:#a990dc}
.heal-icon{color:#9bc995}
.ult-icon{color:#e88463}
.skill-label{font-size:7px;font-weight:800;line-height:9px;text-align:center;letter-spacing:.4px}
.skill-button small{position:absolute;right:6px;top:4px;font-size:8px;color:#d0c3a9}
.skill-button .cooldown{position:absolute;inset:auto 0 0;height:0;background:rgba(5,7,9,.75);transition:height .2s}
.skill-button.ultimate{border-color:#ad704d}
.skill-button.unavailable{filter:grayscale(.8);opacity:.62}
.bottom-nav{position:absolute;z-index:4;left:0;right:0;bottom:0;padding:7px max(10px,env(safe-area-inset-left)) max(8px,env(safe-area-inset-bottom));min-height:67px;display:flex;justify-content:space-around;align-items:center;background:linear-gradient(0deg,rgba(7,9,11,.98),rgba(12,14,16,.94));border-top:1px solid rgba(205,176,120,.2)}
.nav-item{position:relative;width:20%;height:50px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:3px;background:transparent;color:#777a7b}
.nav-item span{font-size:20px;line-height:24px}
.nav-item small{font-size:8px;letter-spacing:1px;font-weight:700}
.nav-item.active{color:var(--gold-bright)}
.nav-item.active:before{content:"";position:absolute;top:-8px;width:25px;height:2px;background:var(--gold-bright);box-shadow:0 0 9px #ddbb78}
.nav-dot{display:none;position:absolute;width:6px;height:6px;top:8px;right:26%;border-radius:50%;background:#e5a84e}
.nav-dot.show{display:block}
.toast{position:absolute;z-index:12;top:19%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:#171816ee;border:1px solid #d5ad68;color:#eadbbd;padding:10px 16px;font-size:11px;box-shadow:0 8px 30px #0008;pointer-events:none;white-space:nowrap}
.toast.show{opacity:1;transform:translate(-50%,0)}
.panel-wrap,.modal-wrap{position:absolute;inset:0;z-index:10;display:none;align-items:flex-end;justify-content:center}
.panel-wrap.open,.modal-wrap.open{display:flex}
.panel-backdrop{position:absolute;inset:0;background:rgba(0,0,0,.62);backdrop-filter:blur(4px)}
.game-panel{position:relative;width:min(690px,100%);max-height:min(78vh,740px);overflow:auto;background:linear-gradient(145deg,#191a1b,#101215 70%);border:1px solid rgba(212,177,106,.35);border-bottom:0;box-shadow:0 -16px 70px #000b;padding:22px clamp(18px,5vw,36px) max(26px,env(safe-area-inset-bottom));animation:rise .23s ease}
@keyframes rise{from{transform:translateY(50px);opacity:.4}
to{transform:translateY(0);opacity:1}
}
.panel-head{display:flex;align-items:flex-start;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:14px;margin-bottom:17px}
.eyebrow{font-size:8px;color:var(--gold);letter-spacing:2px;font-weight:700}
.panel-head h2{font:600 23px Cinzel,serif;margin:4px 0 0}
.close-button{width:32px;height:32px;background:#242525;border:1px solid #4d473b;color:#d4c29d;font-size:19px}
.panel-body{font-size:12px;color:#d7d2c8}
