.small-button,.action-button,.class-card button{background:linear-gradient(180deg,#9d804c,#64502f);border:1px solid #c5a568;color:#fff4d8;font-size:10px;font-weight:800;letter-spacing:.7px;padding:9px 12px}
.small-button:disabled,.action-button:disabled{opacity:.42}
.action-button{width:100%;margin-top:13px;padding:13px}
.inline-actions{display:flex;gap:8px}
.inline-actions>*{flex:1}
.rarity-common{color:#e7e5df}
.rarity-uncommon{color:#84d18b}
.rarity-rare{color:#77b7ff}
.rarity-epic{color:#c496ee}
.rarity-legendary{color:#ffae60}
.rarity-mythic{color:#ff6667}
.rarity-divine{color:#ffe27d}
.item-card{display:flex;align-items:center;gap:12px;margin:8px 0}
.item-glyph{width:36px;height:36px;display:grid;place-items:center;background:#2c2a25;border:1px solid currentColor;font-size:18px}
.item-info{flex:1}
.item-info strong{display:block;font-size:11px}
.item-info small{color:#9a978e;font-size:9px}
.item-stat{font-size:9px;color:#bdb29e}
.empty-state{text-align:center;padding:30px;color:#8e8b82;border:1px dashed #44413b;margin:10px 0}
.skill-grid,.class-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}
.skill-card h3,.class-card h3{margin:0 0 5px;font:600 13px Cinzel,serif;color:#e9d8b4}
.skill-card p,.class-card p{color:#9c9b96;font-size:10px;line-height:1.5;margin:0 0 8px}
