.modal-wrap{align-items:center;padding:20px}
.modal-card{position:relative;width:min(420px,100%);background:linear-gradient(145deg,#1e1e1d,#111315);border:1px solid #c7a263;padding:26px 22px;text-align:center;box-shadow:0 20px 70px #000}
.modal-icon{font-size:40px;color:#e5c27e;text-shadow:0 0 20px #c4944c;margin-bottom:7px}
.modal-card h2{font:600 22px Cinzel,serif;margin:0 0 8px}
.modal-card p{font-size:11px;color:#aaa69b;line-height:1.6}
.reward-list{display:flex;justify-content:center;gap:18px;margin:18px 0;color:#e8d8b5;font-size:12px}
.reward-list strong{color:#efc86e}
.loading{position:absolute;inset:0;z-index:20;background:#090b0e;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;transition:opacity .7s}
.loading.done{opacity:0;pointer-events:none}
.loader-mark{color:#e3bd72;font-size:38px;animation:pulse 1.4s infinite}
@keyframes pulse{50%{transform:scale(1.2);text-shadow:0 0 25px #eac878}
}
.loading strong{font:600 12px Cinzel,serif;letter-spacing:2px}
.loading span{font-size:8px;color:#9b8b68;letter-spacing:3px}

