.bottom-nav .nav-item{width:16.666%;}
.currency-stack{position:absolute;right:clamp(14px,4vw,38px);top:112px;display:grid;gap:6px;pointer-events:none}
.currency-stack .currency{position:static;pointer-events:auto;min-width:102px;justify-content:space-between;backdrop-filter:blur(8px);box-shadow:0 5px 16px #0006}
.currency-stack .gold-currency{border-color:#d1ab6340}
.currency-stack .crystal-currency{border-color:#9c8bd14a;color:#ddd5ff}
.currency-stack .crystal-currency .coin,.currency-stack .crystal-currency button{color:#c4adff}
.currency-stack .currency button{min-width:22px;min-height:24px}
.boss-intro{position:absolute;z-index:6;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;padding:24px;background:radial-gradient(ellipse at center,rgba(49,17,19,.78),rgba(8,8,10,.88) 58%,rgba(5,6,8,.95));opacity:0;visibility:hidden;pointer-events:none;transition:opacity .55s,visibility .55s}
.boss-intro:before,.boss-intro:after{content:"";position:absolute;left:8%;right:8%;height:1px;background:linear-gradient(90deg,transparent,#b77c61,transparent);box-shadow:0 0 18px #d26349}
.boss-intro:before{top:28%}.boss-intro:after{bottom:28%}
.boss-intro.show{opacity:1;visibility:visible;animation:intro-enter 3.2s ease both}
.boss-intro span{font-size:9px;letter-spacing:4px;color:#d4a980;text-transform:uppercase;margin-bottom:15px}
.boss-intro strong{font:700 clamp(25px,6vw,48px) Cinzel,serif;letter-spacing:clamp(2px,1vw,8px);color:#eee0c4;text-shadow:0 0 24px #a93831,0 3px 8px #000;animation:boss-title 3.2s ease both}
.boss-intro small{margin-top:13px;font-size:8px;letter-spacing:3px;color:#ae9e89}
@keyframes intro-enter{0%{opacity:0}12%,75%{opacity:1}100%{opacity:0}}
@keyframes boss-title{0%{transform:scale(1.12);filter:blur(8px);letter-spacing:12px}18%,72%{transform:scale(1);filter:blur(0)}100%{transform:scale(.97)}}
.crystal-rewards,.shop-history{padding:14px;margin:12px 0 16px;background:linear-gradient(130deg,rgba(32,29,25,.92),rgba(19,20,22,.95));border:1px solid rgba(220,190,135,.19);box-shadow:inset 0 1px #ffffff08}
.shop-section-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:11px}
.shop-section-title h3{margin:4px 0 0;font:600 15px Cinzel,serif;color:#eee0c4}
.crystal-balance{padding:7px 10px;border:1px solid #9a82d044;background:#7361a118;color:#d9caff;font-weight:800;font-size:11px;white-space:nowrap}
.reward-chip{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;border-top:1px solid #ffffff0d}
.reward-chip strong,.history-row span{display:block;color:#e5dfd3;font-size:10px}
.reward-chip small,.history-row small{display:block;color:#8f8c85;font-size:8px;margin-top:3px;line-height:1.4}
.reward-chip .small-button{min-width:70px;padding:8px 9px;font-size:8px}
.shop-tabs{position:sticky;top:-1px;z-index:2;display:flex;gap:6px;overflow-x:auto;padding:5px 0 11px;background:#111417;scrollbar-width:none}
.shop-tabs::-webkit-scrollbar{display:none}
.shop-tabs button{flex:1;min-width:max-content;padding:10px 12px;background:#1a1c1e;border:1px solid #393630;color:#a8a398;font-size:8px;font-weight:800;letter-spacing:1px;transition:background .2s,color .2s,border-color .2s}
.shop-tabs button.active{background:linear-gradient(135deg,#54452c,#30291e);border-color:#b5965d;color:#ffe4ae;box-shadow:0 0 16px #c39b4a1a}
.shop-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.shop-card{min-width:0;overflow:hidden;background:linear-gradient(150deg,#202224,#131517 68%);border:1px solid #393735;box-shadow:0 8px 18px #0004;transition:transform .2s,border-color .2s}
.shop-card:hover{transform:translateY(-2px);border-color:#8f7547}
.shop-card.owned{border-color:#8d784b66}
.shop-art{position:relative;height:112px;display:grid;place-items:center;overflow:hidden;background:radial-gradient(ellipse at 50% 70%,color-mix(in srgb,var(--art-a),transparent 58%),transparent 62%),linear-gradient(135deg,color-mix(in srgb,var(--art-a),#151719 82%),color-mix(in srgb,var(--art-b),#101214 77%));border-bottom:1px solid #ffffff0d}
.shop-art:before{content:"";position:absolute;width:90px;height:90px;border:1px solid color-mix(in srgb,var(--art-a),transparent 55%);transform:rotate(45deg);box-shadow:0 0 25px color-mix(in srgb,var(--art-a),transparent 80%)}
.shop-art span{position:relative;font-size:42px;color:var(--art-a);filter:drop-shadow(0 0 13px var(--art-a));text-shadow:0 4px 8px #000}
.shop-art i{position:absolute;top:8px;right:8px;padding:4px 6px;background:#151713d9;border:1px solid #b89a5c;color:#e9d39f;font-style:normal;font-size:7px;letter-spacing:1px}
.shop-copy{padding:11px}
.shop-category{font-size:7px;letter-spacing:1.5px;color:#ba9c62;font-weight:800;text-transform:uppercase}
.shop-copy h3{font:600 13px Cinzel,serif;margin:5px 0;color:#eee3cf;line-height:1.3}
.shop-copy p{min-height:35px;margin:0;color:#9b9992;font-size:9px;line-height:1.45}
.shop-price{margin:9px 0 7px;color:#e5ca91;font-size:10px;font-weight:800}
.billing-note{display:block;min-height:22px;margin:-3px 0 6px;color:#85827a;font-size:7px;line-height:1.4}
.shop-buy{width:100%;min-height:34px;padding:8px 5px;background:linear-gradient(180deg,#9d804c,#64502f);border:1px solid #c5a568;color:#fff4d8;font-size:8px;font-weight:800;letter-spacing:.6px}
.shop-buy.real-money{background:linear-gradient(180deg,#343347,#242334);border-color:#8173b3;color:#e1d9ff}
.shop-buy:disabled{opacity:.5;cursor:default}
.shop-history{margin-top:16px}
.history-row{display:flex;justify-content:space-between;gap:10px;padding:9px 0;border-top:1px solid #ffffff0d}
.history-row small{text-align:right;white-space:nowrap}
.shop-muted{font-size:9px;color:#96938b;line-height:1.5}
.billing-disclaimer{margin:11px 0 0;padding:9px;background:#101114;border-left:2px solid #726394;color:#898691;font-size:8px;line-height:1.55}
.modal-actions{display:flex;gap:8px;align-items:center;margin-top:14px}
.modal-actions>*{flex:1;margin:0}
.shop-confirm-price{padding:12px;background:#131518;border:1px solid #ffffff12;color:#aaa49a;font-size:10px;line-height:2}
.shop-confirm-price strong{color:#e8d2a3}

@media(min-width:760px){.shop-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.shop-art{height:132px}.currency-stack{top:112px}}
@media(max-width:520px){.currency-stack{top:auto;right:10px;bottom:168px;gap:5px}.currency-stack .currency{min-width:94px;padding:4px 7px;font-size:9px}.shop-shortcut{min-width:47px;height:34px;padding:0 6px}.shop-shortcut small{font-size:6px}.bottom-nav .nav-item{width:16.666%;gap:2px}.nav-item span{font-size:18px}.nav-item small{font-size:6px;letter-spacing:.5px}.shop-grid{gap:7px}.shop-art{height:88px}.shop-art:before{width:68px;height:68px}.shop-art span{font-size:34px}.shop-copy{padding:9px}.shop-copy h3{font-size:11px}.shop-copy p{font-size:8px;min-height:38px}.shop-price{font-size:9px}.shop-tabs button{padding:9px 10px}.crystal-rewards,.shop-history{padding:11px}.reward-chip{gap:7px}.reward-chip small{max-width:190px}.boss-intro:before{top:34%}.boss-intro:after{bottom:34%}}
@media(max-height:650px){.game-panel{max-height:78vh}.currency-stack{bottom:142px}.skill-dock{bottom:83px}.boss-intro:before{top:24%}.boss-intro:after{bottom:24%}}

