-height:24px;color:#e0bf79;text-shadow:0 0 12px currentColor}.sweep-icon{color:#a990dc}.heal-icon{color:#9bc995}.ult-icon{color:#e88463}.skill-label{font-size:7px;font-weight:800;line-height:9px;text-align:center;letter-spacing:.4px}.skill-button small{position:absolute;right:6px;top:4px;font-size:8px;color:#d0c3a9}.skill-button .cooldown{position:absolute;inset:auto 0 0;height:0;background:rgba(5,7,9,.75);transition:height .2s}.skill-button.ultimate{border-color:#ad704d}.skill-button.unavailable{filter:grayscale(.8);opacity:.62}.bottom-nav{position:absolute;z-index:4;left:0;right:0;bottom:0;padding:7px max(10px,env(safe-area-inset-left)) max(8px,env(safe-area-inset-bottom));min-height:67px;display:flex;justify-content:space-around;align-items:center;background:linear-gradient(0deg,rgba(7,9,11,.98),rgba(12,14,16,.94));border-top:1px solid rgba(205,176,120,.2)}.nav-item{position:relative;width:20%;height:50px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:3px;background:transparent;color:#777a7b}.nav-item span{font-size:20px;line-height:24px}.nav-item small{font-size:8px;letter-spacing:1px;font-weight:700}.nav-item.active{color:var(--gold-bright)}.nav-item.active:before{content:"";position:absolute;top:-8px;width:25px;height:2px;background:var(--gold-bright);box-shadow:0 0 9px #ddbb78}.nav-dot{display:none;position:absolute;width:6px;height:6px;top:8px;right:26%;border-radius:50%;background:#e5a84e}.nav-dot.show{display:block}.toast{position:absolute;z-index:12;top:19%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:#171816ee;border:1px solid #d5ad68;color:#eadbbd;padding:10px 16px;font-size:11px;box-shadow:0 8px 30px #0008;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.panel-wrap,.modal-wrap{position:absolute;inset:0;z-index:10;display:none;align-items:flex-end;justify-content:center}.panel-wrap.open,.modal-wrap.open{display:flex}.panel-backdrop{position:absolut