101: function maxHp(){return Math.floor((100+state.attributes.vitality*12+state.level*8+gearStat('vitality')*10)*(state.classKey==='NECROMANCER'?1.15:1))}
102: function attackPower(){return Math.floor((8+state.attributes.strength*2+state.level*2+gearStat('attack'))*(state.classKey==='WARRIOR'?1.2:1))}
103: function defense(){return Math.floor(state.attributes.vitality*.6+state.attributes.agility*.22+gearStat('defense')+(state.classKey==='NECROMANCER'?2:0))}
104: function gearStat(key){return Object.values(state.gear).reduce((n,item)=>n+(item?.stats?.[key]||0),0)}
105: function critChance(){return Math.min(45,5+state.attributes.agility*.45+gearStat('crit'))}
106: function xpNeeded(){return Math.floor(100*Math.pow(state.level,1.42))}
107: function xpPercent(){return Math.max(0,Math.min(1,state.xp/xpNeeded()))}
108: function formatNum(n){return Math.floor(n).toLocaleString()}
