function updateEffects(dt){for(const e of [...effects]){e.life-=dt;const p=Math.max(0,e.life/e.max);if(e.kind==='ring'){e.mesh.scale.setScalar(1+(1-p)*.7);e.mesh.material.opacity=p}else if(e.kind==='grow'){e.mesh.scale.set(1,1+(1-p)*1.4,1);e.mesh.material.opacity=p*.55}else if(e.kind==='particle'){e.mesh.position.addScaledVector(e.velocity,dt);e.velocity.y-=3*dt;e.mesh.material.opacity=p}else{e.mesh.scale.multiplyScalar(1+dt*2);e.mesh.material.opacity=p}if(e.life<=0){worldScene.remove(e.mesh);e.mesh.geometry.dispose();if(e.mesh.material.dispose)e.mesh.material.dispose();effects=effects.filter(x=>x!==e)}}}
function renderFrame(){const dt=Math.min(.05,clock.getDelta()),t=clock.elapsedTime;updateCombat(dt,t);updateEffects(dt);for(const flame of ambientFlames){const pulse=.82+Math.sin(t*8+flame.seed)*.18;flame.mesh.scale.set(.8+pulse*.22,1.1+pulse*.25,.8+pulse*.22);flame.light.intensity=14+pulse*8}if(player){player.userData.cape.rotation.z=Math.sin(t*2.1)*.045;player.userData.cape.rotation.x=Math.PI+Math.sin(t*1.7)*.025;player.userData.torso.position.y=1.28+Math.sin(t*2)*.012;player.userData.head.position.y=1.92+Math.sin(t*2)*.014;const targetCam=new THREE.Vector3(player.position.x,player.position.y+5.25,player.position.z+8.8);camera.position.lerp(targetCam,1-Math.pow(.001,dt));camera.lookAt(player.position.x,1.02,player.position.z-1.2)}renderer.render(worldScene,camera);autoSaveTimer+=dt;if(autoSaveTimer>10){autoSaveTimer=0;save()}}
