const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const tab = targets.find(t => t.type === 'page');
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0; const pending = new Map(); const errors = [];
  ws.onmessage = event => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
    if (msg.method === 'Runtime.exceptionThrown') errors.push(msg.params.exceptionDetails.text);
    if (msg.method === 'Log.entryAdded' && msg.params.entry.level === 'error') errors.push(msg.params.entry.text);
  };
  const send = (method, params = {}) => new Promise(resolve => { const n = ++id; pending.set(n, resolve); ws.send(JSON.stringify({id:n,method,params})); });
  const evalJS = async expression => (await send('Runtime.evaluate', {expression, awaitPromise:true, returnByValue:true})).result.result.value;
  await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable');
  await send('Page.navigate', {url:'http://127.0.0.1:8765'}); await sleep(6000);
  const initial = await evalJS(`({title:document.title, loading:document.querySelector('#loading').className, hud:!!document.querySelector('#enemy-name')?.textContent, billing:typeof window.rankUpBilling, shopText:document.querySelector('#game-panel').innerText.slice(0,80)})`);
  await evalJS(`document.querySelector('#open-shop').click()`); await sleep(200);
  const shop = await evalJS(`({open:document.querySelector('#panel-wrap').classList.contains('open'), title:document.querySelector('#game-panel h2').textContent, cards:document.querySelectorAll('.shop-card').length, realMoney:document.querySelectorAll('[data-action="billing-purchase"]').length, disclaimer:document.querySelector('.billing-disclaimer')?.textContent.includes('never simulates payment')})`);
  await evalJS(`document.querySelector('[data-shop-category="gold"]').click()`); await sleep(100);
  const gold = await evalJS(`({items:document.querySelectorAll('.shop-card').length, name:document.querySelector('.shop-card h3')?.textContent})`);
  await evalJS(`document.querySelector('[data-action="confirm-shop-purchase"]').click()`); await sleep(100);
  const modal = await evalJS(`({open:document.querySelector('#modal-wrap').classList.contains('open'), title:document.querySelector('#modal-card h2')?.textContent})`);
  await evalJS(`document.querySelector('[data-action="buy-crystal-product"]').click()`); await sleep(100);
  const cancel = await evalJS(`({open:document.querySelector('#modal-wrap').classList.contains('open'), toast:document.querySelector('#toast').textContent})`);
  await evalJS(`document.querySelector('[data-shop-category="crystals"]').click()`); await sleep(100);
  await evalJS(`document.querySelector('[data-action="billing-purchase"]').click()`); await sleep(100);
  const billing = await evalJS(`({history:JSON.parse(localStorage.getItem('rank-up-awakening-v1')).purchaseHistory.length, crystals:JSON.parse(localStorage.getItem('rank-up-awakening-v1')).crystals, toast:document.querySelector('#toast').textContent})`);
  await send('Page.captureScreenshot', {format:'png'}).then(async m => { if(m.result?.data) require('fs').writeFileSync('/tmp/opencode/rankup-shop.png', Buffer.from(m.result.data,'base64')); });
  console.log(JSON.stringify({initial,shop,gold,modal,cancel,billing,errors},null,2)); ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

